# -- Bounds propagation (interval arithmetic) ------------------------
## CVXPY SOURCE: atom.py:116-146 (#3080).
## bounds_from_args: an atom's interval bounds from its arguments' bounds.
## Default is unbounded; atoms override with the relevant utilities/bounds.R
## helper (Batches 3-4). get_bounds combines that with sign info and is cached
## (CVXPY @compute_once).

method(bounds_from_args, Atom) <- function(x) {
  unbounded(x@shape)
}

method(get_bounds, Atom) <- function(x) {
  cached <- cache_get(x, "get_bounds")
  if (!cache_miss(cached)) return(cached)
  ba <- bounds_from_args(x)
  result <- refine_bounds_from_sign(ba[[1L]], ba[[2L]], is_nonneg(x), is_nonpos(x))
  cache_set(x, "get_bounds", result)
  result
}

