# -- canonicalize ----------------------------------------------------
## CVXPY SOURCE: atom.py lines 337-356

method(canonicalize, Atom) <- function(x) {
  ## Constant atoms (with no parameters) -> wrap as Constant
  if (is_constant(x) && length(parameters(x)) == 0L) {
    return(canonical_form(Constant(value(x))))
  }
  ## Recursively canonicalize args
  arg_objs <- vector("list", length(x@args))
  constraints <- list()
  for (i in seq_along(x@args)) {
    cf <- canonical_form(x@args[[i]])
    arg_objs[[i]] <- cf[[1L]]
    constraints <- c(constraints, cf[[2L]])
  }
  ## Graph implementation
  data <- get_data(x)
  gi <- graph_implementation(x, arg_objs, x@shape, data)
  list(gi[[1L]], c(constraints, gi[[2L]]))
}

# -- value -----------------------------------------------------------
## CVXPY SOURCE: atom.py lines 379-403

method(value, Atom) <- function(x) {
  ## Check if any parameter lacks a value
  params <- parameters(x)
  if (length(params) > 0L) {
    for (p in params) {
      if (is.null(value(p))) return(NULL)
    }
  }
  ## Evaluate
  .atom_value_impl(x)
}

## Internal value implementation (recursive)
## CVXPY SOURCE: atom.py lines 385-403
.atom_value_impl <- function(x) {
  if (0L %in% x@shape) return(numeric(0))
  arg_values <- vector("list", length(x@args))
  for (i in seq_along(x@args)) {
    arg_val <- value(x@args[[i]])
    ## A NULL arg makes higher-level values NULL, unless atom is constant
    if (is.null(arg_val) && !is_constant(x)) return(NULL)
    arg_values[[i]] <- arg_val
  }
  numeric_value(x, arg_values)
}

# -- grad: chain-rule walker ------------------------------------------
## CVXPY SOURCE: atom.py:405-453 (Atom.grad property).
## Walks the expression DAG, calling .grad(x, values) at each atom to get
## per-arg Jacobians, and composes via the chain rule against each child
## Expression's grad() (which is recursive). Returns a list keyed by
## variable id (as.character) of sparse Jacobians of shape
## (prod(var@shape), prod(x@shape)).

.is_scalar <- function(z) is.numeric(z) && length(z) == 1L

method(grad, Atom) <- function(x) {
  ## Constants short-circuit: zero Jacobians for every variable in scope.
  if (is_constant(x)) {
    return(.constant_grad(x))
  }

  ## Pull values for each arg; if any is missing, propagate NULL up.
  arg_values <- vector("list", length(x@args))
  for (i in seq_along(x@args)) {
    v <- value(x@args[[i]])
    if (is.null(v)) {
      return(.error_grad(x))
    }
    arg_values[[i]] <- v
  }

  ## Per-arg Jacobians from the .grad hook.
  grad_self <- .grad(x, arg_values)

  ## Compose against each child's chain via matrix multiplication (or
  ## scalar multiplication when either operand is a scalar). Mirrors
  ## CVXPY's atom.py:430-451 line-for-line.
  result <- list()
  for (idx in seq_along(x@args)) {
    grad_arg <- grad(x@args[[idx]])
    for (key in names(grad_arg)) {
      ga <- grad_arg[[key]]
      gs <- grad_self[[idx]]
      if (is.null(ga) || is.null(gs)) {
        ## Propagate NULL using single-bracket assignment so the entry
        ## is set to NULL rather than removed.
        result[key] <- list(NULL)
      } else {
        if (.is_scalar(ga) || .is_scalar(gs)) {
          D <- ga * gs
        } else {
          D <- ga %*% gs
        }
        ## Collapse 1x1 result to a scalar to match CVXPY's
        ## np.isscalar/sp.shape == (1, 1) handling.
        if (!.is_scalar(D)) {
          dD <- dim(D)
          if (!is.null(dD) && all(dD == c(1L, 1L))) {
            D <- as.numeric(D[1L, 1L])
          }
        }
        if (key %in% names(result)) {
          result[[key]] <- result[[key]] + D
        } else {
          result[[key]] <- D
        }
      }
    }
  }
  result
}

# -- .grad: per-atom hook (abstract default) --------------------------
## CVXPY SOURCE: atom.py:455-466 (Atom._grad abstract method).
## Each non-affine non-leaf atom must register a method(.grad, MyAtom)
## returning a list of one sparse Jacobian per argument, shape
## (prod(arg.shape), prod(self.shape)).
##
## AffAtom has its own .grad method (built from the LinOp coefficient);
## see atoms/affine/affine_atom.R.

method(.grad, Atom) <- function(x, values, ...) {
  cli_abort(c(
    ".grad() not yet implemented for {.cls {S7::S7_class(x)@name}}.",
    "i" = "Each non-affine atom must register a {.fn method(.grad, MyAtom)} hook.",
    "i" = "See {.help dev_handbook} for the porting convention."
  ))
}

# -- .column_grad: per-fiber hook (abstract default) --------------
## Used by axis-aware atoms that inherit `.grad(AxisAtom)` from
## atoms/axis_atom.R. Each axis atom registers `method(.column_grad,
## MyAtom)` returning the per-fiber gradient (a numeric vector or
## NULL-on-domain-violation). Atoms that don't go through `.column_grad`
## register their own `method(.grad, MyAtom)` and never reach this
## default.

method(.column_grad, Atom) <- function(x, value, ...) {
  cli_abort(c(
    ".column_grad() not yet implemented for {.cls {S7::S7_class(x)@name}}.",
    "i" = "Axis atoms must register either {.fn method(.column_grad, MyAtom)} (for fiber-level grad) or {.fn method(.grad, MyAtom)} (to bypass the axis machinery).",
    "i" = "See {.help dev_handbook} for the porting convention."
  ))
}

# -- domain ----------------------------------------------------------
## CVXPY SOURCE: atom.py lines 469-474
## self._domain() + [con for arg in self.args for con in arg.domain]

## Default atom_domain: no extra constraints
## CVXPY SOURCE: atom.py::_domain -- default returns []
method(atom_domain, Atom) <- function(x) list()

method(domain, Atom) <- function(x) {
  ## CVXPY: self._domain() + [con for arg in self.args for con in arg.domain]
  my_domain <- atom_domain(x)
  arg_domains <- unlist(lapply(x@args, domain), recursive = FALSE)
  if (is.null(arg_domains)) arg_domains <- list()
  c(my_domain, arg_domains)
}

# -- atoms -----------------------------------------------------------
## CVXPY SOURCE: atom.py lines 496-502
## Returns atom types present in the expression tree.
## In R, we collect S7 class objects, deduplicated by class name.

method(atoms, Atom) <- function(x) {
  nargs <- length(x@args)
  parts <- vector("list", nargs + 1L)
  for (i in seq_len(nargs)) {
    parts[[i]] <- atoms(x@args[[i]])
  }
  parts[[nargs + 1L]] <- list(S7_class(x))
  .unique_atom_types(unlist(parts, recursive = FALSE))
}

## Helper: deduplicate a list of S7 class objects by class name
.unique_atom_types <- function(class_list) {
  n <- length(class_list)
  if (n == 0L) return(list())
  seen <- new.env(hash = TRUE, parent = emptyenv())
  result <- vector("list", n)
  ri <- 0L
  for (cls in class_list) {
    name <- if (inherits(cls, "S7_class")) cls@name else as.character(cls)
    if (!exists(name, envir = seen, inherits = FALSE)) {
      assign(name, TRUE, envir = seen)
      ri <- ri + 1L
      result[[ri]] <- cls
    }
  }
  result[seq_len(ri)]
}

